head.script:
scwin.onpageload = function() {
	requires("uiplugin.popup");
};

scwin.fn_openPopup = function() {
	var options = {
		id: "popup1",
		type: "litewindow",
		width: "700px",
		height: "300px",
		popupName: "TestPage1",
		modal: true,
		closeAction: "scwin.closePop",
		resizable: false,
		frameMode: "wframe",
		useATagBtn: true,
		title: false
	};
	$w.openPopup("/sample/common_link/p_popup_wframeURL-WEFF-327_(WSQ-3652)_sub.xml", options);
};

scwin.closePop = function() {
	return true;
};

scwin.anchor1_onclick = function() {
	scwin.fn_openPopup();
};
